const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const api=async(path,opts={})=>{const headers={...(opts.headers||{})};if(opts.method&&opts.method.toUpperCase()!=='GET')headers['X-CSRF-Token']=window.APP_CSRF||'';const r=await fetch(path,{credentials:'same-origin',...opts,headers});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Request failed');return d};
const toast=m=>{const t=$('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3200)};
const money=n=>n==null?'Price on request':'UGX '+Number(n).toLocaleString('en-UG');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const modal=html=>{$('#modalContent').innerHTML=html;$('#modal').classList.add('show')};
const close=()=>$('#modal').classList.remove('show');
$('#modalClose').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')close()});
$('#mobileMenu').onclick=()=>$('#nav').classList.toggle('open');
let pendingConnectId=null;
function authForm(type){const reg=type==='register';modal(`<h2>${reg?'Create your buyer account':'Welcome back'}</h2><p class="sub">${pendingConnectId?'Create an account or log in to securely message the seller.':(reg?'Join the marketplace and start connecting with customers.':'Log in to manage adverts and messages.')}</p><form id="authForm">${reg?'<div class="form-field"><label>Full name</label><input name="full_name" required></div>':''}<div class="form-field"><label>Email address</label><input name="email" type="email" required></div>${reg?'<div class="form-field"><label>Phone number</label><input name="phone" required></div>':''}<div class="form-field"><label>Password</label><input name="password" type="password" minlength="8" required></div><button class="btn btn-primary">${reg?'Create account':'Log in'}</button></form>${!reg?'<p class="sub" style="text-align:right"><a href="#" id="forgotPassword" style="color:#146b4b;font-weight:800">Forgot password?</a></p>':''}<p class="sub" style="margin-top:18px;text-align:center">${reg?'Already registered?':'New here?'} <a href="#" id="switchAuth" style="color:#146b4b;font-weight:800">${reg?'Log in':'Create account'}</a></p>`);$('#authForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{await api('/api/auth/'+(reg?'register':'login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const next=pendingConnectId;pendingConnectId=null;if(next){location.href=location.pathname+'?connect='+encodeURIComponent(next)}else location.reload()}catch(err){toast(err.message)}};$('#switchAuth').onclick=e=>{e.preventDefault();authForm(reg?'login':'register')};const forgot=$('#forgotPassword');if(forgot)forgot.onclick=async e=>{e.preventDefault();const email=$('#authForm [name=email]').value.trim();if(!email){toast('Enter your email address first.');return}try{const result=await api('/api/auth/recover',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email})});toast(result.message||'Check your email for a reset link.')}catch(err){toast(err.message)}}}
$$('[data-open]').forEach(b=>b.onclick=()=>authForm(b.dataset.open));
async function loadListings(q=''){const grid=$('#listingGrid');grid.innerHTML='<div class="loading">Finding great local offers…</div>';try{const cat=$('#categoryFilter').value;const d=await api('/api/listings?q='+encodeURIComponent(q)+'&category='+encodeURIComponent(cat));if(d.categories){$('#categoryFilter').innerHTML='<option value="">All categories</option>'+d.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');$('#categoryFilter').value=cat;$('#categoryGrid').innerHTML=d.categories.slice(0,8).map((c,i)=>`<button class="category-tile" data-cat="${c.id}"><span>${['🌾','📱','🚗','🏡','🧱','👗','🪑','🛠️'][i%8]}</span><b>${esc(c.name)}</b></button>`).join('');$$('[data-cat]').forEach(x=>x.onclick=()=>{ $('#categoryFilter').value=x.dataset.cat;filterListings()})}
if(!d.listings?.length){grid.innerHTML='<div class="empty">No active adverts yet. Be the first to post something!</div>';return}
grid.innerHTML=d.listings.map(a=>`<article class="listing-card" id="advert-${a.id}"><div class="listing-image">${a.image_url?`<img src="${esc(a.image_url)}" alt="${esc(a.title)}">`:'🛍️'}</div><div class="listing-content"><div class="listing-meta"><span>${esc(a.location||'Northern Uganda')}</span><span>● Active</span></div><h3>${esc(a.title)}</h3><p>${esc(a.description||'Connect with this seller to learn more.')}</p><div class="listing-foot"><span class="listing-price">${money(a.price)}</span><button data-connect="${a.id}">CONNECT ↗</button></div><button class="report-link" data-report="${a.id}">Report this advert</button></div></article>`).join('');
$$('[data-connect]').forEach(b=>b.onclick=()=>connect(b.dataset.connect));$$('[data-report]').forEach(b=>b.onclick=()=>reportAdvert(b.dataset.report));
}catch(e){let detail=e.message||'Unknown error';try{const s=await api('/api/status');detail=s.message||detail}catch(statusError){detail=statusError.message||detail}grid.innerHTML=`<div class="empty market-error"><strong>Marketplace could not load</strong><p>${esc(detail)}</p><button class="btn btn-outline" id="retryMarketplace">Try again</button></div>`;const retry=$('#retryMarketplace');if(retry)retry.onclick=()=>loadListings(q);}}

async function loadPromotions(){
 const stage=$('#promotionStage');if(!stage)return;
 let items=[],index=0;
 const draw=()=>{
  if(!items.length){stage.innerHTML='<div class="promotion-placeholder"><b>Local businesses</b><span>Featured offers will appear here.</span></div>';return}
  const item=items[index%items.length],href=item.target_url||'/marketplace';
  const external=/^https?:\/\//i.test(href);
  stage.innerHTML=`<article class="promotion-card">${item.image_url?`<img class="promotion-image" src="${esc(item.image_url)}" alt="${esc(item.title)}">`:'<div class="promotion-image promotion-no-image">✦</div>'}<div class="promotion-copy"><span class="promotion-label">${esc(item.label||'Sponsored')}</span><b>${esc(item.title)}</b><p>${esc(item.description||'Discover this featured local offer.')}</p><a href="${esc(href)}" ${external?'target="_blank" rel="noopener noreferrer"':''}>View offer ↗</a></div></article>`;
  const bar=$('#promotionProgress');if(bar){bar.style.transition='none';bar.style.width='0';requestAnimationFrame(()=>{bar.style.transition='width 20s linear';bar.style.width='100%'})}
 };
 try{const d=await api('/api/promotions');items=d.promotions||[];draw();if(window.__promotionTimer)clearInterval(window.__promotionTimer);window.__promotionTimer=setInterval(()=>{if(items.length>1){index=(index+1)%items.length;draw()}},20000)}
 catch(e){stage.innerHTML='<div class="promotion-placeholder"><b>Featured local offers</b><span>Promotions will appear here when available.</span></div>';console.warn('Promotions could not load:',e.message)}
}
async function filterListings(){await loadListings($('#searchInput').value)}
$('#searchBtn').onclick=filterListings;$('#refreshListings').onclick=filterListings;$('#categoryFilter').onchange=filterListings;$('#searchInput').addEventListener('keydown',e=>{if(e.key==='Enter')filterListings()});$$('[data-search]').forEach(b=>b.onclick=()=>{$('#searchInput').value=b.dataset.search;filterListings()});
async function connect(id){if(!window.APP_USER){location.href='/register?connect='+encodeURIComponent(id);return}modal(`<h2>Connect with seller</h2><p class="sub">Your message is private to you and this advert's seller. You must be signed in to send or read messages; other buyers cannot access this conversation.</p><form id="connectForm"><div class="form-field"><label>Your message</label><textarea name="message" rows="4" required maxlength="5000" placeholder="Hello, I am interested in your advert…"></textarea></div><button class="btn btn-primary">Send message</button></form>`);$('#connectForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({advertisement_id:id,message:new FormData(e.target).get('message')})});close();toast('Message sent.');openMessages(d.conversation_id)}catch(err){toast(err.message)}}}
function reportAdvert(id){if(!window.APP_USER){authForm('login');toast('Log in to report an advert.');return}modal(`<h2>Report this advert</h2><p class="sub">Tell our moderation team what concerns you.</p><form id="reportForm"><div class="form-field"><label>Reason</label><select name="reason" required><option>Fraud or scam</option><option>Prohibited item</option><option>Misleading information</option><option>Harassment or abuse</option><option>Other</option></select></div><div class="form-field"><label>Details (optional)</label><textarea name="details" rows="3" maxlength="1500"></textarea></div><button class="btn btn-primary">Submit report</button></form>`);$('#reportForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/reports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...Object.fromEntries(new FormData(e.target)),advertisement_id:id})});close();toast('Report submitted for review.')}catch(err){toast(err.message)}}}
async function postAdvert(){if(!window.APP_USER){authForm('register');toast('Create an account before posting an advert.');return}try{const d=await api('/api/pricing');modal(`<h2>Post a new advert</h2><p class="sub">Your advert is published automatically once Pesapal verifies your payment.</p><form id="advertForm" enctype="multipart/form-data"><div class="form-field"><label>Advert title</label><input name="title" required maxlength="120"></div><div class="form-field"><label>Description</label><textarea name="description" rows="3" required maxlength="5000"></textarea></div><div class="form-grid"><div class="form-field"><label>Category</label><select name="category_id" id="postCategory" required></select></div><div class="form-field"><label>Price (UGX, optional)</label><input name="price" type="number" min="0"></div></div><div class="form-grid"><div class="form-field"><label>Location / town</label><input name="location" required placeholder="e.g. Gulu City"></div><div class="form-field"><label>District</label><input name="district" placeholder="e.g. Gulu"></div></div><div class="form-field"><label>Advert duration</label><select name="duration_id" id="duration" required>${d.durations.map(x=>`<option value="${x.id}">${esc(x.label)} — ${money(x.price_ugx)}</option>`).join('')}</select></div><div class="form-field"><label>Cover image (JPG, PNG or WebP, max 5MB)</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"></div><button class="btn btn-primary">Continue to Pesapal checkout →</button></form>`);const cats=await api('/api/listings');$('#postCategory').innerHTML=cats.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');$('#advertForm').onsubmit=async e=>{e.preventDefault();const r=await fetch('/api/advert',{method:'POST',body:new FormData(e.target),credentials:'same-origin',headers:{'X-CSRF-Token':window.APP_CSRF||''}});const j=await r.json();if(!r.ok){toast(j.error||'Could not start checkout');return}location.href=j.checkout_url}}catch(e){toast(e.message)}}
['postHero','howPost','ctaPost'].forEach(id=>{const button=$('#'+id);if(button)button.onclick=postAdvert;});
async function openMessages(selected=null){try{const d=await api('/api/messages');modal(`<h2>Messages</h2><p class="sub">Private conversations between buyers and sellers.</p><div class="messenger"><aside class="conversation-list">${d.conversations.length?d.conversations.map(c=>`<button class="conversation-item ${selected===c.id?'selected':''}" data-conv="${c.id}"><b>${esc(c.other_party)}</b><small>${esc(c.advertisements?.title||'Marketplace advert')}</small><span>${esc(c.last_message?.body||'Start the conversation')}</span>${c.unread_count?`<i>${c.unread_count}</i>`:''}</button>`).join(''):'<p class="sub">No conversations yet. Use CONNECT on an advert to start one.</p>'}</aside><section class="chat-panel" id="chatPanel"><div class="chat-empty">Choose a conversation to read and reply.</div></section></div>`);$$('[data-conv]').forEach(b=>b.onclick=()=>openMessages(b.dataset.conv));if(selected)await renderThread(selected)}catch(e){toast(e.message)}}
async function renderThread(id){const d=await api('/api/messages/'+id);const c=d.conversation;const panel=$('#chatPanel');if(!panel)return;panel.innerHTML=`<div class="chat-heading"><b>${esc(c.advertisements?.title||'Marketplace conversation')}</b><small>Private chat</small></div><div class="chat-history" id="chatHistory">${d.messages.map(m=>`<div class="bubble ${m.sender_id===window.APP_USER.id?'mine':'theirs'}"><p>${esc(m.body)}</p><small>${esc(m.sender?.full_name||'Member')} · ${new Date(m.created_at).toLocaleString()}</small></div>`).join('')}</div><form id="replyForm" class="reply-form"><textarea name="message" rows="2" maxlength="5000" required placeholder="Write a message…"></textarea><button class="btn btn-primary">Send</button></form>`;const history=$('#chatHistory');history.scrollTop=history.scrollHeight;$('#replyForm').onsubmit=async e=>{e.preventDefault();const message=new FormData(e.target).get('message');try{await api('/api/messages/'+id,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message})});await renderThread(id)}catch(err){toast(err.message)}}}
async function openMyAdverts(){const d=await api('/api/my-adverts');modal(`<h2>My adverts</h2><p class="sub">Track advert review and publication status.</p>${d.adverts.length?d.adverts.map(a=>`<div class="admin-row"><div><b>${esc(a.title)}</b><small>${esc(a.location)} · ${esc(a.advertisement_durations?.label||'')}</small></div><span class="status status-${a.status}">${esc(a.status.replace('_',' '))}</span></div>`).join(''):'<p class="sub">You have not posted any adverts yet.</p>'}`)}

