const connectAfterAuth=new URLSearchParams(location.search).get('connect');if(connectAfterAuth){if(window.APP_USER){history.replaceState({},'',location.pathname);setTimeout(()=>connect(connectAfterAuth),250)}else{pendingConnectId=connectAfterAuth;authForm('register')}}
const paymentParams=new URLSearchParams(location.search);
const paymentResult=paymentParams.get('payment');
const dashboardAfterPayment=paymentParams.get('dashboard');
const dashboardSection=paymentParams.get('section');
if(paymentResult==='received'){
 toast('Payment verified successfully. Your advert is published and ready in your seller dashboard.');
 if(dashboardAfterPayment==='seller'&&window.APP_USER&&window.APP_USER.role!=='owner'&&window.APP_USER.role!=='admin'){
  history.replaceState({},'',location.pathname);
  setTimeout(async()=>{await sellerDashboard();if(dashboardSection==='adverts'){const nav=$('.seller-workspace [data-seller-section="adverts"]');if(nav)nav.click()}},200);
 }
}else if(paymentResult==='check_failed')toast('We could not confirm the payment yet. Your advert has not been confirmed as published. Please check your seller dashboard or contact support with your Pesapal receipt.');
else if(paymentResult==='checking')toast('Payment submitted. We are waiting for Pesapal confirmation. Your advert will appear after verification.');
const pageTargets={marketplace:'#market',categories:'#categories','how-it-works':'#how'};
loadListings().then(()=>{const target=pageTargets[document.body.dataset.page];if(target){const section=$(target);if(section)section.scrollIntoView({behavior:'smooth',block:'start'})}});
loadPromotions();

/* Shared loading feedback for all clicked buttons and async requests. */
if(!window.__buttonLoadingInstalled){
 window.__buttonLoadingInstalled=true;
 let activeButton=null, fallbackTimer=null;
 const restoreButton=button=>{
  if(!button)return;
  button.classList.remove('is-loading');button.removeAttribute('aria-busy');
  const spinner=button.querySelector('.btn-spinner');if(spinner)spinner.remove();
  button.disabled=false;
  if(activeButton===button)activeButton=null;
  if(fallbackTimer)clearTimeout(fallbackTimer);
 };
 document.addEventListener('click',event=>{
  const button=event.target.closest('button');
  if(!button||button.disabled||button.dataset.noLoading!==undefined)return;
  if(activeButton&&activeButton!==button)restoreButton(activeButton);
  activeButton=button;button.classList.add('is-loading');button.setAttribute('aria-busy','true');
  const spinner=document.createElement('span');spinner.className='btn-spinner';spinner.setAttribute('aria-hidden','true');button.appendChild(spinner);
  fallbackTimer=setTimeout(()=>restoreButton(button),12000);
 },true);
 const nativeFetch=window.fetch.bind(window);
 window.fetch=(...args)=>{const button=activeButton;return nativeFetch(...args).finally(()=>{if(button&&activeButton===button)restoreButton(button)})};
}
